#!/usr/bin/env python3
"""Writes script/ep51.en.json … ep60.en.json from one compact table (the batch's words live here until an episode is
voiced; after that the JSON is the source and this file is the record of how the batch was drafted). Modelled on
tools/write_scripts_41_50.py; the plan and the verse check are in script/ARC-51-60.md.

    python3 -I tools/write_scripts_51_60.py [51 52 …]  write all ten, or only the episodes named
    python3 -I tools/estimate.py --ep 51 --write       then predict the voice lengths
    node tools/gate.mjs --ep 51                        and gate the script
"""
import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = "BORI Critical Edition"
MADE = "Voices: synthetic · Drawn in code"
CE = "GRETIL e-text of the constituted text, lab/ce; star passages and appendix lines are apparatus and were not used; Ganguli (vulgate) only as a reading aid"

def L(id, text, speaker=None, say=None, **o):
    d = {"id": id}
    if speaker: d["speaker"] = speaker
    d["speed"] = o.pop("speed", 1.0 if speaker else NARR)
    d["text"] = text
    d["say"] = say or text.strip('"')
    d["est"] = 3.0
    d["pre"] = o.pop("pre", 250)
    d["post"] = o.pop("post", 300)
    d.update(o)
    return d

def hook(text, speaker=None, say=None, **o):
    return L("hook", text, speaker, say, pre=60, post=o.pop("post", 1100), speed=o.pop("speed", 1.1), role="hook", caption=False, **o)

def nxt(title):
    return {"id": "next", "text": f"Next: {title}", "voice": False, "est": 1.1, "role": "next", "caption": False, "cam": "push", "note": "The NEXT › band over the cliffhanger image, with the source line; dissolve into frame 1."}

def arcend(title, pal, note):
    return {"id": "arcend", "text": f"The end of an arc · {title}", "voice": False, "est": 1.5, "caption": False, "pal": pal, "cam": "still", "note": "The ARC-END CARD (silent): " + note}

EP = {}
NARR = 1.1
TITLES = {50: "Born on an Island", 51: "The Burden of the Earth", 52: "Gods in Disguise", 53: "The King and the Hermitage", 54: "The Girl the Birds Protected", 55: "A Marriage Without Witnesses",
          56: "The Boy Who Tamed Lions", 57: "\"I Do Not Know You\"", 58: "The Voice from the Sky", 59: "The Secret of Reviving the Dead", 60: "Kacha Dies Twice", 61: "The Curse at Parting"}

